import { isRecord, type Country } from "./content.ts";
export { isCountry, isRecord, type Country } from "./content.ts";
import { compilePattern, matchesPattern } from "./pattern.ts";
export { matchesPattern };

export type FieldValue = string | number | boolean;
export type FieldKind = "text" | "number" | "select" | "date" | "checkbox";
type FieldPurpose =
  | "dateOfBirth"
  | "vehicleYear"
  | "identityDocument"
  | "licensePlate";

type Rule =
  | { operator: "required" | "email" | "vehicleYearRange"; message: string }
  | {
      operator: "minLength" | "maxLength" | "min" | "max" | "minimumAge";
      argument: number;
      message: string;
    }
  | {
      operator: "pattern" | "minDate" | "maxDate";
      argument: string;
      message: string;
    };

type FieldCommon = {
  id: string;
  label: string;
  helpText: string;
  errorMessage: string;
  required: boolean;
  order: number;
  rules: readonly Rule[];
  purpose?: FieldPurpose;
};
type Option = { id: string; label: string };
export type FieldDefinition = FieldCommon &
  (
    | { kind: "text" | "date"; defaultValue?: string }
    | { kind: "number"; defaultValue?: number }
    | { kind: "checkbox"; defaultValue?: boolean }
    | { kind: "select"; defaultValue?: string; options: readonly Option[] }
  );

export type FormDefinition = {
  schemaVersion: 1;
  country: Country;
  fields: readonly FieldDefinition[];
};
export type DraftEntry = { kind: FieldKind; value: FieldValue | null };
export type QuoteDraft = Readonly<Record<string, DraftEntry>>;

const kinds: readonly FieldKind[] = [
  "text",
  "number",
  "select",
  "date",
  "checkbox",
];
const purposeKinds: Record<FieldPurpose, FieldKind> = {
  dateOfBirth: "date",
  vehicleYear: "number",
  identityDocument: "text",
  licensePlate: "text",
};
const MAX_FIELDS = 40;
const MAX_OPTIONS = 60;
const MAX_RULES = 12;
const MAX_TEXT = 240;
const MAX_INPUT = 256;

export function isSafeId(value: unknown): value is string {
  return (
    typeof value === "string" &&
    /^[a-z][a-z0-9-]{0,39}$/.test(value) &&
    value !== "constructor"
  );
}

export function isFieldKind(value: unknown): value is FieldKind {
  return kinds.some((kind) => kind === value);
}

function copy(value: unknown, allowEmpty = false): value is string {
  return (
    typeof value === "string" &&
    value.length <= MAX_TEXT &&
    (allowEmpty || !!value.trim())
  );
}

function boundedInteger(value: unknown): value is number {
  return typeof value === "number" && Number.isSafeInteger(value) && value >= 0;
}

export function isCalendarDate(value: unknown): value is string {
  if (typeof value !== "string" || !/^\d{4}-\d{2}-\d{2}$/.test(value))
    return false;
  const [year, month, day] = value.split("-").map(Number);
  if (year < 1 || month < 1 || month > 12 || day < 1) return false;
  const leap = year % 4 === 0 && (year % 100 !== 0 || year % 400 === 0);
  return (
    day <=
    [31, leap ? 29 : 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31][month - 1]
  );
}

export function isKindValue(
  kind: FieldKind,
  value: unknown,
): value is FieldValue {
  switch (kind) {
    case "text":
      return typeof value === "string" && [...value].length <= MAX_INPUT;
    case "select":
      return isSafeId(value);
    case "date":
      return isCalendarDate(value);
    case "number":
      return typeof value === "number" && Number.isFinite(value);
    case "checkbox":
      return typeof value === "boolean";
  }
}
import { isRecord, type Country } from "./content.ts";

export const MAX_PLANS = 40;
const MAX_PRICE = 999_999_999_999;
const MAX_LIST_ENTRIES = 20;

export const planCurrency = { co: "COP", cl: "CLP" } as const;
export type PlanPrice = {
  amountMinor: number;
  currency: (typeof planCurrency)[Country];
};

export type Plan = {
  id: string;
  name: string;
  shortDescription: string;
  basePrice: PlanPrice;
  coverages: readonly string[];
  benefits: readonly string[];
  order: number;
  recommended: boolean;
};

export type PlanCatalog = {
  schemaVersion: 1;
  country: Country;
  plans: readonly Plan[];
};

export function isPlanId(value: unknown): value is string {
  return typeof value === "string" && /^[a-z0-9][a-z0-9-]{0,39}$/.test(value);
}

function isNonnegativeInteger(value: unknown): value is number {
  return typeof value === "number" && Number.isSafeInteger(value) && value >= 0;
}

export function decodePlanPrice(
  input: unknown,
  country: Country,
): PlanPrice | null {
  if (!isRecord(input)) return null;
  const { amountMinor, currency } = input;
  if (
    currency !== planCurrency[country] ||
    !isNonnegativeInteger(amountMinor) ||
    amountMinor > MAX_PRICE
  )
    return null;
  return { amountMinor, currency: planCurrency[country] };
}

function isPlanText(value: unknown): value is string {
  return (
    typeof value === "string" && value.length <= 240 && value.trim().length > 0
  );
}

function isTextList(value: unknown): value is string[] {
  return (
    Array.isArray(value) &&
    value.length <= MAX_LIST_ENTRIES &&
    value.every(isPlanText)
  );
}

function decodePlan(value: unknown, country: Country): Plan | null {
  if (!isRecord(value)) return null;
  const {
    id,
    name,
    shortDescription,
    order,
    coverages,
    benefits,
    recommended,
  } = value;
  const basePrice = decodePlanPrice(value["basePrice"], country);
  if (
    !isPlanId(id) ||
    !isPlanText(name) ||
    !isPlanText(shortDescription) ||
    !isNonnegativeInteger(order) ||
    !isTextList(coverages) ||
    !isTextList(benefits) ||
    typeof recommended !== "boolean" ||
    !basePrice
  )
    return null;
  return {
    id,
    name,
    shortDescription,
    order,
    coverages,
    benefits,
    recommended,
    basePrice,
  };
}

export function decodePlanCatalog(
  input: unknown,
  country: Country,
): PlanCatalog | null {
  if (
    !isRecord(input) ||
    input["schemaVersion"] !== 1 ||
    input["country"] !== country
  )
    return null;
  const entries = input["plans"];
  if (!Array.isArray(entries) || entries.length > MAX_PLANS) return null;
  const plans: Plan[] = [];
  const ids = new Set<string>();
  for (const entry of entries) {
    const plan = decodePlan(entry, country);
    if (!plan || ids.has(plan.id)) return null;
    ids.add(plan.id);
    plans.push(plan);
  }
  plans.sort((a, b) => a.order - b.order || (a.id < b.id ? -1 : 1));
  return { schemaVersion: 1, country, plans };
}
